function snapshotAll(cwd,provider='manual'){const paths=statePaths(cwd);ensureLayout(paths);const registry=readJson(paths.registry,{tasks:{}});const results=[];const active=Object.entries(registry.tasks??{}).filter(([,task])=>isActiveStatus(task.status));for(const wt of worktreeRoots(paths.root)){const matches=active.filter(([,task])=>task.worktree===wt);for(const[taskId]of matches)results.push(snapshot(wt,provider,'snapshot-all',{session_id:`manual-${digest(`${wt}:${taskId}`,12)}`},taskId));}if(!active.length)results.push(snapshot(paths.root,provider,'snapshot-all',{session_id:`manual-${digest(paths.root,12)}`}));return results;}
function activeTasks(paths){return Object.values(readJson(paths.registry,{tasks:{}}).tasks??{}).filter(t=>isActiveStatus(t.status)).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)));}
function buildResumePrompt(target,tasks,handoffRel){const listing=tasks.map(t=>`- \`${t.task_id}\` — status \`${t.status}\`, worktree \`${t.worktree}\`, branch \`${t.branch}\`, next: ${t.exact_next_action??'read HANDOFF.md'}`).join('\n')||'- No active tasks found.';return`# Resume all active tasks\n\nTarget environment: **${target}**\nPortable handoff bundle: \`${handoffRel}\`\n\n${listing}\n\nUse the \`agent-continuity\` skill and perform a provider-neutral takeover:\n\n1. Read \`AGENT_CONTINUITY.md\`, all applicable repository instructions, and this bundle's \`manifest.json\`.\n2. Read each task's \`state.json\`, \`HANDOFF.md\`, \`DECISIONS.md\`, \`FINDINGS.md\`, \`TESTS.md\`, and \`SESSION_HISTORY.md\`.\n3. Verify the recorded worktree, branch, HEAD, upstream, staged, unstaged, and untracked state against Git. Git and the filesystem are authoritative.\n4. Do not inspect another provider's private session IDs, credentials, or raw transcripts. The portable handoff is the transfer boundary.\n5. Continue from each verified \`Exact next action\`. Do not redo completed work.\n6. Use one isolated worker/subagent/chat per independent task when supported. Bind each worker to the existing worktree and branch. Never allow two writers in one worktree.\n7. If visible chat creation is unavailable, use subagents; otherwise continue tasks sequentially in this chat.\n8. Update continuity documents after material findings, decisions, coherent edit batches, test results, blockers, commits, branch/worktree changes, and before ending a substantive turn.\n9. Respect project commit/push rules. Without explicit push permission, do not push.\n10. Before switching tools again, invoke the skill with \`handoff all <next-target>\`.\n\nBegin recovery and continue implementation. Do not stop after merely summarizing unless all tasks are blocked or ready for review.\n`;}
function exportBundle(cwd,target='any',scope='all'){const paths=statePaths(cwd);ensureLayout(paths);snapshotAll(cwd,'manual-export');let tasks=activeTasks(paths);if(scope==='current')tasks=tasks.filter(t=>t.worktree===paths.root);const candidates=[];for(const task of tasks){const source=join(paths.portable,'tasks',task.task_id);const completion=handoffComplete(source);if(isProvisionalTaskId(task.task_id)&&!completion.complete)continue;candidates.push({task,source,completion});}if(!candidates.length)throw new Error('export refused: no active task has an exportable handoff (only provisional placeholders remain). Update HANDOFF.md / state before export.');const complete=candidates.filter(c=>c.completion.complete);if(!complete.length)throw new Error('export refused: no task has a complete semantic handoff (placeholders remain). Update HANDOFF.md / state before export.');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/T/,'-').slice(0,15);const bundle=join(paths.portable,'handoffs',stamp);ensureDir(bundle);const manifestTasks=[];for(const{task,source,completion}of complete){const dest=join(bundle,'tasks',task.task_id);ensureDir(dest);for(const name of['state.json','HANDOFF.md','DECISIONS.md','FINDINGS.md','TESTS.md','SESSION_HISTORY.md'])if(existsSync(join(source,name)))copyFileSync(join(source,name),join(dest,name));manifestTasks.push({...task,semantic_handoff_complete:completion.complete,handoff_problems:completion.problems});}const rel=relative(paths.base,bundle);const manifest={schema_version:VERSION,created_at:now(),target,scope,source_repository:paths.root,git_common_dir:paths.common,portable_only:true,contains_provider_session_ids:false,contains_raw_transcripts:false,tasks:manifestTasks};atomicJson(join(bundle,'manifest.json'),manifest);atomicText(join(bundle,'RESUME_ALL.md'),buildResumePrompt(target,manifestTasks,rel));const registry=readJson(paths.registry,{tasks:{},provider_runs:{},handoffs:[]});registry.handoffs.push({created_at:manifest.created_at,path:rel,target,scope});registry.handoffs=registry.handoffs.slice(-50);registry.updated_at=now();atomicJson(paths.registry,registry);return{bundle,resume_prompt:join(bundle,'RESUME_ALL.md'),manifest};}
function buildGlobalResumePrompt(target,tasks,bundlePath){const lines=['# Resume all active tasks across providers and repositories','',`Target environment: \`${target}\``,`Global handoff bundle: \`${bundlePath}\``,'','Use the Agent Continuity protocol and perform the takeover autonomously:','','1. Read `manifest.json`, then read every copied task\'s `state.json`, `HANDOFF.md`, `DECISIONS.md`, `FINDINGS.md`, `TESTS.md`, and `SESSION_HISTORY.md`.','2. For every task, verify the recorded repository, worktree, branch, HEAD, staged/unstaged/untracked state, upstream, and recent commits. Git and the filesystem are authoritative.','3. Preserve each stable task ID. Do not merge unrelated tasks merely because they share a branch or repository.','4. Never allow two writers in one worktree. Use separate worktrees for independent tasks, otherwise process them sequentially.','5. Continue from each verified exact next action. Do not repeat completed work.','6. Respect repository-specific instructions, validation, commit, push, security, and worktree rules. Without explicit push permission, do not push.','7. Maintain provider-neutral continuity files after material findings, decisions, coherent edit batches, test results, blockers, and before switching tools again.','8. Do not inspect or transfer raw provider session IDs, raw transcripts, transcript paths, credentials, or the private continuity layer.','9. When the environment supports independent agents, assign one task per independent worktree and keep one coordinator. Otherwise continue sequentially.','10. Finish each turn with task status, worktree, branch, HEAD, validation, commit/push state, and exact next action.','','## Tasks',''];for(const item of tasks)lines.push(`- \`${item.task_id}\` — repo \`${item.repository}\`, worktree \`${item.worktree}\`, branch \`${item.branch}\`, status \`${item.status}\`, next: ${item.exact_next_action}`);lines.push('','Begin recovery and continue implementation. Do not stop after only summarizing unless every task is blocked or ready for review.','');return lines.join('\n');}
function exportGlobalBundle(target='any',provider=null){const snapshotResult=snapshotActiveGlobalRuns(provider);const grouped=new Map();for(const record of activeGlobalRuns(provider)){if(!record.repository||!record.task_id)continue;const key=`${record.repository}\0${record.task_id}`;if(!grouped.has(key))grouped.set(key,{repository:record.repository,task_id:record.task_id,worktree:record.worktree??record.repository,branch:record.branch,head:record.head,provider_run_refs:[],providers:[]});const item=grouped.get(key);if(record.provider_run_ref&&!item.provider_run_refs.includes(record.provider_run_ref))item.provider_run_refs.push(record.provider_run_ref);if(record.provider&&!item.providers.includes(record.provider))item.providers.push(record.provider);}const gp=ensureGlobalLayout();const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/T/,'-').slice(0,15);const bundle=join(dirname(gp.base),'handoffs',stamp);ensureDir(bundle);const tasks=[];try{for(const item of [...grouped.values()].sort((a,b)=>`${a.repository}:${a.task_id}`.localeCompare(`${b.repository}:${b.task_id}`))){try{const paths=statePaths(item.worktree);ensureLayout(paths);const source=join(paths.portable,'tasks',item.task_id);const completion=handoffComplete(source);if(!completion.complete)continue;const state=readJson(join(source,'state.json'),{});const repoKey=digest(item.repository,16);const dest=join(bundle,'repositories',repoKey,'tasks',item.task_id);ensureDir(dest);for(const name of['state.json','HANDOFF.md','DECISIONS.md','FINDINGS.md','TESTS.md','SESSION_HISTORY.md'])if(existsSync(join(source,name)))copyFileSync(join(source,name),join(dest,name));tasks.push({...item,status:normalizeStatus(state.status??'planned'),objective:state.objective,exact_next_action:state.exact_next_action,branch:state.branch??item.branch,head:state.head??item.head,copied_task_path:relative(bundle,dest),semantic_handoff_complete:true,handoff_problems:[]});}catch(error){debug('export-global-task',error);}}if(!tasks.length)throw new Error('export refused: no task has a complete semantic handoff (placeholders remain). Update HANDOFF.md / state before export.');const manifest={schema_version:VERSION,created_at:now(),target,scope:'global-active-runs',portable_only:true,contains_provider_session_ids:false,contains_raw_transcripts:false,active_run_ttl_seconds:activeRunTtlSeconds(),snapshot_result:{captured_at:snapshotResult.captured_at,error_count:snapshotResult.errors.length,errors:snapshotResult.errors},tasks};atomicJson(join(bundle,'manifest.json'),manifest,0o600);atomicText(join(bundle,'RESUME_ALL.md'),buildGlobalResumePrompt(target,tasks,bundle),0o600);return{bundle,resume_prompt:join(bundle,'RESUME_ALL.md'),manifest};}catch(error){rmSync(bundle,{recursive:true,force:true});throw error;}}
function suspendGlobalRun(runRef){const gp=ensureGlobalLayout();const data=readJson(gp.runs,{runs:{}});const record=data.runs?.[runRef];if(!record)throw new Error(`Unknown provider run reference: ${runRef}`);Object.assign(record,{lifecycle:'suspended',last_event:'manual-suspend',updated_at:now()});data.updated_at=now();atomicJson(gp.runs,data,0o600);return record;}
function stageForUsage(data){const rate=data.rate_limits??{};const context=data.context_window??{};const values={five_hour:normalizePercentage(rate.five_hour?.used_percentage),seven_day:normalizePercentage(rate.seven_day?.used_percentage),context:normalizePercentage(context.used_percentage)};return{stage:usageStage(values),values};}
function statusline(data){const cwd=expandHome(data.workspace?.current_dir??data.cwd??process.cwd());const{stage,values}=stageForUsage(data);const session=providerId(data);try{const paths=statePaths(cwd);ensureLayout(paths);const ref=providerRef('claude-code',session);atomicJson(join(paths.private,'usage',`${ref}.json`),{updated_at:now(),stage,session_id:session,provider_run_ref:ref,...values},0o600);const globalUsage=recordAndFanoutUsage('claude-code',values,'claude-statusline','exact',ref);if(globalUsage)markStartupReadyForProvider('claude-code',globalUsage,'claude-statusline');if(stage!=='green'){const reqPath=join(paths.private,'requests',`${ref}.json`);const old=readJson(reqPath,{});const order={green:0,warning:1,checkpoint:2,handoff:3,critical:4};if(order[stage]>=order[old.stage??'green'])atomicJson(reqPath,{requested_at:old.requested_at??now(),updated_at:now(),stage,provider:'claude-code',provider_run_ref:ref,raw_session_id:session,usage:values,acknowledged_at:old.acknowledged_at},0o600);}}catch(error){debug('statusline',error);}const parts=[];if(values.five_hour!==null)parts.push(`5h ${values.five_hour.toFixed(0)}%`);if(values.seven_day!==null)parts.push(`7d ${values.seven_day.toFixed(0)}%`);if(values.context!==null)parts.push(`ctx ${values.context.toFixed(0)}%`);const marker={green:'✓',warning:'!',checkpoint:'↻',handoff:'⇄',critical:'⛔'}[stage];return`AC ${marker} ${stage}${parts.length?` · ${parts.join(' ')}`:''}`;}
function pendingRequest(paths,provider,rawId){const ref=providerRef(provider,rawId);const candidates=[];const local=readJson(join(paths.private,'requests',`${ref}.json`),null);if(local&&!local.acknowledged_at)candidates.push(local);const global=globalPendingRequest(ref);if(global)candidates.push(global.value);if(!candidates.length)return null;const order={green:0,warning:1,checkpoint:2,handoff:3,critical:4};return candidates.sort((a,b)=>order[b.stage??'green']-order[a.stage??'green'])[0];}
function acknowledgeIfFresh(paths,taskId,provider,rawId){const ref=providerRef(provider,rawId);const localPath=join(paths.private,'requests',`${ref}.json`);const local=readJson(localPath,null);const global=globalPendingRequest(ref);const candidates=[];if(local&&!local.acknowledged_at)candidates.push(local);if(global)candidates.push(global.value);if(!candidates.length)return false;const requested=candidates.map(v=>parseTime(v.requested_at)?.getTime()).filter(Number.isFinite);if(!requested.length)return false;let mtime;try{mtime=statSync(join(paths.portable,'tasks',taskId,'HANDOFF.md')).mtimeMs;}catch{return false;}if(mtime<Math.max(...requested))return false;if(local&&!local.acknowledged_at){local.acknowledged_at=now();atomicJson(localPath,local,0o600);}markGlobalRequestAcknowledged(ref);return true;}
async function hook(provider,data){const cwd=expandHome(data.cwd??data.workspace?.current_dir??process.cwd());const event=String(data.hook_event_name??data.event??'unknown');const result=snapshot(cwd,provider,event,data);const paths=Object.fromEntries(Object.entries(result.paths).map(([k,v])=>[k,v]));const raw=providerId(data);const taskId=result.task_id;const runRef=result.provider_run_ref;const extracted=extractProviderUsage(provider,data);if(Object.values(extracted.values).some(v=>v!==null))recordAndFanoutUsage(provider,extracted.values,extracted.source,extracted.confidence,runRef);acknowledgeIfFresh(paths,taskId,provider,raw);const req=pendingRequest(paths,provider,raw);const taskRel=`.agent-continuity/portable/tasks/${taskId}`;
  const inferredSessionTitle=provider==='claude-code'&&result.task_naming_source==='first-prompt'&&result.renamed_from?promptTitle(data.prompt):null;
  if(event.toLowerCase()==='sessionstart'){const statusline=provider==='claude-code'?ensureClaudeStatuslineIntegration():null;const startup=await startupUsageCheck(provider,String(runRef),extracted.values,extracted.source,extracted.confidence);const conflicts=globalWriteConflicts().filter(item=>item.worktree===result.snapshot.worktree);const conflictText=conflicts.length?' Concurrent-run conflict detected for this worktree. Do not write until one run is suspended or independent work is moved to another worktree.':'';const statuslineText=statusline?.changed?' Claude usage monitoring was configured automatically; it becomes exact after the first API response and remains active across sessions.':'';let startupPolicy='';if(provider==='claude-code'&&startup.phase==='awaiting-first-response')startupPolicy=' Claude Code does not expose fresh subscription limits to SessionStart before the first API response. For the initial bootstrap cycle, load continuity state and inspect only low-cost metadata; do not begin a large edit, build, test suite, or subagent fan-out. After this response, the status-line probe records exact limits and the Stop hook automatically continues the original request when safe, without requiring the user to repeat it.';else if(provider==='cursor'&&startup.phase==='unknown')startupPolicy=' Cursor did not expose an official quota value and no trusted usage adapter returned one. Continue only with incremental, frequently checkpointed batches; never claim an exact remaining quota.';else if(startup.phase==='unknown')startupPolicy=' Exact startup quota could not be obtained. Use conservative incremental checkpoints and avoid starting an operation that cannot be safely interrupted.';const context=`Agent Continuity is active. Provider-neutral task: ${taskId}. Read AGENT_CONTINUITY.md and ${taskRel}/HANDOFF.md plus state.json before substantive work. Provider session IDs and raw transcripts are private and must not be copied into portable files. Update the handoff after material findings, decisions, coherent edit batches and tests. ${startupSummaryText(startup)} Usage monitoring capability for this provider: ${JSON.stringify(PROVIDER_CAPABILITIES[provider]??{})}.${statuslineText}${startupPolicy}${conflictText}`;const specific={hookEventName:event,additionalContext:context};if(provider==='claude-code'&&!sessionTitle(data))specific.sessionTitle=`${taskId} [${result.snapshot.branch}]`.slice(0,100);return{hookSpecificOutput:specific,...(provider==='cursor'?{systemMessage:context,additional_context:context}:{})};}
  if(['Stop','stop'].includes(event)&&runRef){if(provider==='claude-code')refreshClaudeStartupStateFromCache(String(runRef));const continuation=startupStopContinuation(provider,String(runRef));if(continuation&&!data.stop_hook_active)return{decision:'block',reason:continuation.reason};}
  if(['precompact','pre_compact'].includes(event.toLowerCase())){const instruction=`Compaction is about to occur. Before compaction, update ${taskRel}/HANDOFF.md, DECISIONS.md, FINDINGS.md, TESTS.md, SESSION_HISTORY.md and state.json with all durable task context, including the exact next action and current Git/worktree state. Keep portable files sanitized.`;return{hookSpecificOutput:{hookEventName:event,additionalContext:instruction},...(provider==='cursor'?{systemMessage:instruction,additional_context:instruction}:{})};}
  if(req&&['UserPromptSubmit','PostToolBatch','PostToolUse','Stop','stop','beforeSubmitPrompt','postToolUse','preToolUse'].includes(event)){const stage=req.stage;const instruction=`Continuity threshold \`${stage}\` was reached. Before starting another large operation, update ${taskRel}/HANDOFF.md, DECISIONS.md, FINDINGS.md, TESTS.md and state.json with the current objective, acceptance criteria, completed work, exact next action, changed files, findings, decisions, test results, blockers, branch/worktree/HEAD and dirty state. Keep it provider-neutral and sanitized. Then run the continuity export for the appropriate target.`;if(['Stop','stop'].includes(event)&&!data.stop_hook_active&&['checkpoint','handoff','critical'].includes(stage))return{decision:'block',reason:instruction};return{hookSpecificOutput:{hookEventName:event,additionalContext:instruction,...(inferredSessionTitle?{sessionTitle:inferredSessionTitle}:{})},...(provider==='cursor'?{systemMessage:instruction,additional_context:instruction}:{})};}
  if(inferredSessionTitle)return{hookSpecificOutput:{hookEventName:event,sessionTitle:inferredSessionTitle}};
  return null;
}
function runOriginalStatusline(payload){const original=config().original_claude_status_line;if(!isObject(original)||original.disabled||!original.command)return'';const args=Array.isArray(original.args)?original.args.map(String):[];const result=run(String(original.command),args,{shell:!args.length,input:payload,timeout:Number(original.timeout??5)*1000});return result.stdout;}
function printList(cwd,asJson=false){const paths=statePaths(cwd);ensureLayout(paths);const registry=readJson(paths.registry,{tasks:{},provider_runs:{}});const tasks=activeTasks(paths).map(task=>({...task,provider_run_details:(task.provider_runs??[]).map(ref=>registry.provider_runs?.[ref]??{provider_run_ref:ref})}));const data={repository:paths.root,tasks,conflicts:continuityConflicts(paths)};if(asJson){console.log(JSON.stringify(data,null,2));return;}console.log(`Repository: ${paths.root}`);if(!tasks.length){console.log('No active tasks.');return;}for(const t of tasks){console.log(`- ${t.task_id}: ${t.status} | ${t.branch} | ${t.worktree} | ${t.exact_next_action}`);for(const r of t.provider_run_details)console.log(`    run ${r.provider_run_ref} | ${r.provider} | ${r.lifecycle} | ${r.last_event}`);}for(const conflict of data.conflicts)console.log(`CONFLICT: ${conflict.worktree} has tasks ${conflict.task_ids.join(', ')}`);}
function resolvePathSafe(path){try{return existsSync(path)?realpathSync(path):resolve(expandHome(path));}catch{return resolve(expandHome(path));}}
function doctor(cwd){const paths=statePaths(cwd);ensureLayout(paths);const locatorLink=join(paths.root,'.agent-continuity');const locatorPointer=join(paths.root,'.agent-continuity-location.json');let privatePermissions=true;if(process.platform!=='win32'){const mode=statSync(paths.private).mode&0o777;privatePermissions=[0o700,0o750].includes(mode);}const continuityRootResolves=existsSync(paths.base);const base=resolvePathSafe(paths.base);let continuityRootMatchesLocator=false;const pointerData=readJson(locatorPointer,null);if(isObject(pointerData)&&pointerData.continuity_root&&resolvePathSafe(pointerData.continuity_root)===base)continuityRootMatchesLocator=true;if(!continuityRootMatchesLocator&&process.platform!=='win32'&&existsSync(locatorLink)){try{if(lstatSync(locatorLink).isSymbolicLink()&&realpathSync(locatorLink)===base)continuityRootMatchesLocator=true;}catch(error){debug('doctor-locator-link',error);}}const checks={platform:process.platform,node_version:process.version,node_lts:process.release.lts??null,git_repository:existsSync(paths.root),portable_registry:existsSync(paths.registry),private_permissions:privatePermissions,continuity_locator:existsSync(locatorLink)||existsSync(locatorPointer),continuity_root_resolves:continuityRootResolves,continuity_root_matches_locator:continuityRootMatchesLocator,claude_skill:existsSync(join(homedir(),'.claude','skills','agent-continuity','SKILL.md')),codex_skill:existsSync(join(homedir(),'.agents','skills','agent-continuity','SKILL.md')),cursor_skill:existsSync(join(homedir(),'.cursor','skills','agent-continuity','SKILL.md'))};console.log(JSON.stringify(checks,null,2));return Object.values(checks).filter(v=>typeof v==='boolean').every(Boolean)?0:1;}

function parseCli(argv){const command=argv.shift();const opts={_:[]};for(let i=0;i<argv.length;i++){const arg=argv[i];if(arg.startsWith('--')){const eq=arg.indexOf('=');const key=(eq>=0?arg.slice(2,eq):arg.slice(2)).replace(/-([a-z])/g,(_,c)=>c.toUpperCase());let value=eq>=0?arg.slice(eq+1):true;if(eq<0&&i+1<argv.length&&!argv[i+1].startsWith('-'))value=argv[++i];opts[key]=value;}else opts._.push(arg);}return{command,opts};}
function num(value){if(value===undefined||value===true)return null;const n=Number(value);return Number.isFinite(n)?n:null;}
async function main(){const{command,opts}=parseCli(process.argv.slice(2));if(!command||['-h','--help','help'].includes(command)){console.log('Agent Continuity commands: snapshot, snapshot-all, snapshot-active, discover, list, rebind, export, export-global, hook, statusline, doctor, usage, runs, suspend-run, conflicts');return 0;}switch(command){case'snapshot':console.log(JSON.stringify(snapshot(expandHome(opts.cwd??'.'),opts.provider??'manual',opts.event??'manual',{},opts.task??null),null,2));break;case'snapshot-all':console.log(JSON.stringify(snapshotAll(expandHome(opts.cwd??'.'),opts.provider??'manual'),null,2));break;case'snapshot-active':console.log(JSON.stringify(snapshotActiveGlobalRuns((opts.provider??'all')==='all'?null:opts.provider),null,2));break;case'discover':console.log(JSON.stringify(discoverClaude(expandHome(opts.cwd??'.'),Number(opts.days??30)),null,2));break;case'list':printList(expandHome(opts.cwd??'.'),Boolean(opts.json));break;case'rebind':console.log(JSON.stringify(rebindProviderRun(expandHome(opts.cwd??'.'),opts.providerRunRef,opts.task),null,2));break;case'export':console.log(JSON.stringify(exportBundle(expandHome(opts.cwd??'.'),opts.target??'any',opts.scope??'all'),null,2));break;case'export-global':console.log(JSON.stringify(exportGlobalBundle(opts.target??'any',(opts.provider??'all')==='all'?null:opts.provider),null,2));break;case'hook':{let input='';for await(const chunk of process.stdin)input+=chunk;const data=input.trim()?JSON.parse(input):{};const output=await hook(opts.provider,data);if(output)console.log(JSON.stringify(Object.fromEntries(Object.entries(output).filter(([,v])=>v!==null&&v!==undefined))));break;}case'statusline':{let input='';for await(const chunk of process.stdin)input+=chunk;const data=JSON.parse(input);const original=runOriginalStatusline(input);console.log(`${original?`${original}\n`:''}${statusline(data)}`);break;}case'doctor':return doctor(expandHome(opts.cwd??'.'));case'usage':{const sub=opts._[0];if(sub==='status')console.log(JSON.stringify(usageSummary(),null,2));else if(sub==='probe')console.log(JSON.stringify((opts.provider??'all')==='all'?await probeAllUsage():await probeUsage(opts.provider),null,2));else if(sub==='set')console.log(JSON.stringify(setManualUsage(opts.provider,num(opts.fiveHour),num(opts.sevenDay),num(opts.context),opts.source??'manual'),null,2));else throw new Error('usage requires status, probe, or set');break;}case'runs':{const runs=activeGlobalRuns((opts.provider??'all')==='all'?null:opts.provider);if(opts.json)console.log(JSON.stringify(runs,null,2));else for(const r of runs)console.log(`${r.provider_run_ref} | ${r.provider} | ${r.task_id} | ${r.worktree} | ${r.branch} | ${r.updated_at}`);break;}case'suspend-run':console.log(JSON.stringify(suspendGlobalRun(opts.providerRunRef),null,2));break;case'conflicts':console.log(JSON.stringify(globalWriteConflicts(),null,2));break;default:throw new Error(`Unknown command: ${command}`);}return 0;}
try{process.exitCode=await main();}catch(error){console.error(`agent-continuity: ${error.name}: ${error.message}`);process.exitCode=1;}
